H.background();
const cx = H.W * 0.5, cy = H.H * 0.54, S = Math.min(H.W, H.H) * 0.30;
const mod = Math.max(0.2, P.mod), arg = P.arg * Math.PI / 180, n = Math.max(2, Math.round(P.n));
const root = Math.pow(mod, 1 / n);
const reach = Math.min(1, root / 2.2);
const Rpix = S;
H.circle(cx, cy, Rpix * reach, { stroke: H.colors.grid, width: 1.5 });
H.line(cx - S - 16, cy, cx + S + 16, cy, { color: H.colors.axis, width: 1 });
H.line(cx, cy - S - 16, cx, cy + S + 16, { color: H.colors.axis, width: 1 });
const highlight = Math.floor(t * 0.8) % n;
for (let k = 0; k < n; k++) {
  const ak = (arg + 2 * Math.PI * k) / n;
  const px = cx + Rpix * reach * Math.cos(ak), py = cy - Rpix * reach * Math.sin(ak);
  const isHi = k === highlight;
  H.line(cx, cy, px, py, { color: isHi ? H.colors.accent2 : H.colors.accent, width: isHi ? 3 : 1.5 });
  H.circle(px, py, isHi ? 7 + Math.sin(t * 3) : 5, { fill: isHi ? H.colors.warn : H.colors.good });
}
H.text("n-th roots: z^(1/n) = r^(1/n)·cis((θ+2πk)/n)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("r = " + mod.toFixed(2) + "   θ = " + P.arg.toFixed(0) + "°   n = " + n, 24, 52, { color: H.colors.sub, size: 13 });
H.text(n + " roots, spaced " + (360 / n).toFixed(0) + "° apart, modulus " + root.toFixed(2), 24, 72, { color: H.colors.good, size: 13 });
H.legend([{ label: "highlighted root", color: H.colors.warn }, { label: "the n roots", color: H.colors.good }], H.W - 200, 28);
